$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$sourcePath='D:\projects\tool-text-parts-http-source-r2.json'
$m=[IO.File]::ReadAllText($sourcePath)|ConvertFrom-Json
$repo=$m.repo.Replace('/','\');$sha=$m.source_commit
function Verify-File([string]$Path,[string]$Sha){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Sha){throw ('Changed input: '+$Path)}}
Verify-File $PSCommandPath $m.script_sha256
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$priorPath=Join-Path $repo 'build\tool-text-parts-server-build-r1\run-record.json'
Verify-File $priorPath $m.native_build_run_sha256
$prior=[IO.File]::ReadAllText($priorPath)|ConvertFrom-Json
if($prior.reason -ne 'completed' -or $prior.exit_code -ne 0 -or -not $prior.host_checks_pass){throw 'Native server build must pass'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$controller=Join-Path 'D:\projects' $m.controller;$config=Join-Path 'D:\projects' $m.config
Verify-File $controller $m.controller_sha256;Verify-File $config $m.config_sha256
foreach($e in $m.source_sha256.PSObject.Properties){Verify-File (Join-Path $repo $e.Name) $e.Value}
